const $=s=>document.querySelector(s),tabs=$('#productTabs'),mock=$('#mockScreen'),frame=$('#screenFrame'),cursor=$('#cursor'),spot=$('#spotlight');
let active=0,scene=0,playing=true,captions=true,muted=false,started=false,timer=null,elapsed=0,lastTick=0,controlsTimer=null;const sceneMs=8000,totalMs=sceneMs*4;
function uiMarkup(p){const labels={statusflow:['Lead queue','DHS checks','Exceptions','Resolved'],stride:['Intake','Flags','Reviews','Proposals'],crm:['Workspace','Automations','Predictive dates','Clients'],thynksign:['Agreements','Templates','Signers','Audit trail']}[p.id];return `<div class="ui"><div class="ui-top"><div class="ui-logo"><i>${p.name.slice(0,1)}</i>${p.name.slice(1)}</div><span>Live workspace&nbsp;&nbsp;●</span></div><div class="ui-body"><aside class="ui-side"><b>Workspace</b>${labels.map((x,i)=>`<span class="${i===1?'on':''}">${x}</span>`).join('')}</aside><section class="ui-main"><h2>${p.scenes[scene][0]}</h2><p>${p.summary}</p><div class="metric-row"><div class="metric"><small>Ready</small><strong>${p.id==='statusflow'?'1 sec':p.id==='stride'?'3 sec':'24'}</strong></div><div class="metric"><small>In progress</small><strong>${scene*7+12}</strong></div><div class="metric"><small>Attention</small><strong>${Math.max(2,9-scene*2)}</strong></div></div><div class="activity"><b>Live activity</b><div class="activity-line hot"></div><div class="activity-line"></div><div class="activity-line" style="width:62%"></div><div class="activity-line" style="width:84%"></div></div></section></div></div>`}
function buildTabs(){tabs.innerHTML=products.map((p,i)=>`<button class="product-tab ${i===0?'active':''}" data-index="${i}">${p.name}</button>`).join('');tabs.addEventListener('click',e=>{const b=e.target.closest('button');if(b)selectProduct(+b.dataset.index,true)})}
function selectProduct(i,announce=false){active=i;scene=0;elapsed=0;playing=true;lastTick=performance.now();document.documentElement.style.setProperty('--product',products[i].accent);[...tabs.children].forEach((b,n)=>b.classList.toggle('active',n===i));$('#worldCount').textContent=`${String(i+1).padStart(2,'0')} / ${String(products.length).padStart(2,'0')}`;$('#productKicker').textContent=products[i].kicker;$('#productTitle').textContent=products[i].name;$('#productSummary').textContent=products[i].summary;$('#chapterList').innerHTML=products[i].scenes.map((s,n)=>`<li class="${n===0?'active':''}">${s[0]}</li>`).join('');renderScene(announce);updatePlay()}
function renderScene(speak=true){const p=products[active],s=p.scenes[scene],sceneImage=p.images?.[scene]||p.image;mock.innerHTML=sceneImage?`<img src="${sceneImage}" alt="${p.name}: ${s[0]}">`:uiMarkup(p);$('#caption').textContent=captions?s[1]:'';[...$('#chapterList').children].forEach((x,n)=>x.classList.toggle('active',n===scene));frame.classList.toggle('zoom',scene===1||scene===2);spot.classList.toggle('show',scene>0);const points=[[22,72],[58,22],[70,55],[42,62]][scene];cursor.style.left=points[0]+'%';cursor.style.top=points[1]+'%';cursor.classList.remove('click');void cursor.offsetWidth;cursor.classList.add('click');spot.style.left=(scene===1?54:scene===2?63:38)+'%';spot.style.top=(scene===1?18:scene===2?47:55)+'%';$('#sideTivi').src=p.tivi?.[scene]||['assets/tivi-think.png','assets/tivi-connect.png','assets/tivi-solved.png','assets/tivi-midnight.png'][scene];if(speak)voice(s[1])}
function voice(text){speechSynthesis.cancel();if(muted||!started)return;const spoken=text.replace(/iThynk/gi,'eye think');const u=new SpeechSynthesisUtterance(spoken);u.rate=.88;u.pitch=.8;u.volume=.96;const voices=speechSynthesis.getVoices();const male=/David|Mark|Guy|Ryan|Daniel|James|George|Google UK English Male/i;u.voice=voices.find(v=>male.test(v.name)&&/^en(-|_)/i.test(v.lang))||voices.find(v=>/^en-ZA$/i.test(v.lang))||voices.find(v=>male.test(v.name+' '+v.lang))||voices.find(v=>v.lang.startsWith('en'))||null;speechSynthesis.speak(u)}
function tick(t){if(!lastTick)lastTick=t;if(playing&&started){elapsed+=t-lastTick;if(elapsed>=totalMs){elapsed=0;selectProduct((active+1)%products.length,true)}const ns=Math.min(3,Math.floor(elapsed/sceneMs));if(ns!==scene){scene=ns;renderScene(true)}$('#progress').style.width=(elapsed/totalMs*100)+'%';$('#time').textContent=`0:${String(Math.floor(elapsed/1000)).padStart(2,'0')} / 0:32`}lastTick=t;requestAnimationFrame(tick)}
function updatePlay(){$('#playBtn').textContent=playing?'Ⅱ':'▶';$('#playBtn').setAttribute('aria-label',playing?'Pause showcase':'Play showcase')}
function showControls(){$('#controls').classList.add('visible');clearTimeout(controlsTimer);controlsTimer=setTimeout(()=>$('#controls').classList.remove('visible'),2200)}
$('#enterBtn').addEventListener('click',()=>{started=true;$('#intro').classList.add('is-leaving');$('#player').classList.add('is-active');selectProduct(0,true);showControls()});
$('#homeBtn').addEventListener('click',()=>{started=false;speechSynthesis.cancel();$('#intro').classList.remove('is-leaving');$('#player').classList.remove('is-active')});
$('#playBtn').addEventListener('click',()=>{playing=!playing;playing?voice(products[active].scenes[scene][1]):speechSynthesis.cancel();updatePlay();showControls()});
$('#soundBtn').addEventListener('click',()=>{muted=!muted;$('#soundBtn').textContent=muted?'Muted':'Sound';if(muted)speechSynthesis.cancel();else voice(products[active].scenes[scene][1]);showControls()});
$('#captionsBtn').addEventListener('click',()=>{captions=!captions;$('#captionsBtn').setAttribute('aria-pressed',captions);$('#caption').textContent=captions?products[active].scenes[scene][1]:'';showControls()});
$('#fullBtn').addEventListener('click',()=>{document.fullscreenElement?document.exitFullscreen():$('#stage').requestFullscreen?.();showControls()});
$('#chaptersToggle').addEventListener('click',()=>{const c=$('#chapters');c.classList.toggle('closed');$('#chaptersToggle').setAttribute('aria-expanded',!c.classList.contains('closed'))});
$('#chapterList').addEventListener('click',e=>{const li=e.target.closest('li');if(!li)return;scene=[...li.parentNode.children].indexOf(li);elapsed=scene*sceneMs;renderScene(true)});
document.addEventListener('mousemove',showControls);document.addEventListener('keydown',e=>{if(e.code==='Space'&&started){e.preventDefault();$('#playBtn').click()}if(e.code==='ArrowRight'&&started)selectProduct((active+1)%products.length,true);if(e.code==='ArrowLeft'&&started)selectProduct((active-1+products.length)%products.length,true)});
buildTabs();selectProduct(0,false);requestAnimationFrame(tick);
